using NUnit.Framework;
using SIL.LCModel;
using FeatVals = System.Collections.Generic.Dictionary<string, string>;

namespace SIL.FieldWorks.XWorks.MorphologyEditor
{
	/// <summary>
	/// A natural class with a generated name counts as user defined once two or more distinct
	/// rules use it, and stays auto-generated while at most one rule does. Each case varies
	/// only what refers to the class.
	/// </summary>
	[TestFixture]
	public class RuleFormulaControlSharedNaturalClassTests : RuleFormulaVcTestBase
	{
		private IPhNCFeatures AddGeneratedClass()
		{
			return AddAutoGeneratedFeatureNaturalClass("s to n", new FeatVals { { "vd", "+" } });
		}

		private static bool IsUserDefined(IPhNCFeatures natClass)
		{
			return RuleFormulaControl.IsFeatureBasedNCUserDefined(natClass);
		}

		/// <summary>
		/// Adds a sequence context owned as the left context of <paramref name="rhs"/>, the
		/// way the rule editor holds an environment of more than one item. The members must
		/// already be owned.
		/// </summary>
		private IPhSequenceContext AddRuleOwnedSequenceContext(IPhSegRuleRHS rhs,
			params IPhPhonContext[] members)
		{
			IPhSequenceContext ctxt =
				Cache.ServiceLocator.GetInstance<IPhSequenceContextFactory>().Create();
			rhs.LeftContextOA = ctxt;
			foreach (IPhPhonContext member in members)
				ctxt.MembersRS.Add(member);
			return ctxt;
		}

		/// <summary>
		/// Adds an output mapping to <paramref name="rule"/> that modifies its input with
		/// <paramref name="natClass"/>.
		/// </summary>
		private IMoModifyFromInput AddModifyMapping(IMoAffixProcess rule, IPhNCFeatures natClass)
		{
			IMoModifyFromInput mapping =
				Cache.ServiceLocator.GetInstance<IMoModifyFromInputFactory>().Create();
			rule.OutputOS.Add(mapping);
			mapping.ModificationRA = natClass;
			return mapping;
		}

		/// <summary>
		/// Adds an environment whose left context is <paramref name="ctxt"/>, used by an affix
		/// allomorph of a new entry.
		/// </summary>
		private IPhEnvironment AddEnvironmentUsedByAnAllomorph(IPhPhonContext ctxt)
		{
			IPhEnvironment env =
				Cache.ServiceLocator.GetInstance<IPhEnvironmentFactory>().Create();
			Cache.LanguageProject.PhonologicalDataOA.EnvironmentsOS.Add(env);
			env.LeftContextRA = ctxt;
			ILexEntry entry = Cache.ServiceLocator.GetInstance<ILexEntryFactory>().Create();
			IMoAffixAllomorph allomorph =
				Cache.ServiceLocator.GetInstance<IMoAffixAllomorphFactory>().Create();
			entry.AlternateFormsOS.Add(allomorph);
			allomorph.PhoneEnvRC.Add(env);
			return env;
		}

		[Test]
		public void AutoNamedClassUsedByTwoRegularRules_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			AddStrucDescNCContext(AddRegularRule("rule B"), natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		[Test]
		public void AutoNamedClassUsedByRegularAndMetathesisRules_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			AddMetathesisNCContext(AddMetathesisRule("rule B"),
				PhMetathesisRuleTags.kidxLeftSwitch, natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		[Test]
		public void AutoNamedClassUsedByRegularAndAffixProcessRules_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			AddInputNCContext(AddAffixProcessRule(), natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		[Test]
		public void AutoNamedClassUsedByTwoAffixProcessMappings_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddModifyMapping(AddAffixProcessRule(), natClass);
			AddModifyMapping(AddAffixProcessRule(), natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		/// <summary>
		/// A member of a multi-item environment is owned by the phonological data, so it
		/// reaches its rule only through the sequence context that rule owns.
		/// </summary>
		[Test]
		public void AutoNamedClassReachedThroughSequenceContext_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddRuleOwnedSequenceContext(AddRegularRule("rule A"),
				AddStandaloneNCContext(natClass));
			AddStrucDescNCContext(AddRegularRule("rule B"), natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		[Test]
		public void AutoNamedClassReachedThroughIterationInSequence_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			IPhIterationContext iteration = AddIterationContext(AddStandaloneNCContext(natClass));
			AddRuleOwnedSequenceContext(AddRegularRule("rule A"), iteration);
			AddStrucDescNCContext(AddRegularRule("rule B"), natClass);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		/// <summary>
		/// One context object refers to the class, yet two rules use that context.
		/// </summary>
		[Test]
		public void ContextSharedBySequencesInTwoRules_IsUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			IPhSimpleContextNC sharedCtxt = AddStandaloneNCContext(natClass);
			AddRuleOwnedSequenceContext(AddRegularRule("rule A"), sharedCtxt);
			AddRuleOwnedSequenceContext(AddRegularRule("rule B"), sharedCtxt);

			Assert.That(IsUserDefined(natClass), Is.True);
		}

		[Test]
		public void AutoNamedClassUsedByOneRule_IsNotUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);

			Assert.That(IsUserDefined(natClass), Is.False);
		}

		[Test]
		public void AutoNamedClassUsedTwiceInOneRule_IsNotUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			IPhSegRuleRHS rhs = AddRegularRule("rule A");
			AddStrucDescNCContext(rhs, natClass);
			AddStrucChangeNCContext(rhs, natClass);

			Assert.That(IsUserDefined(natClass), Is.False);
		}

		[Test]
		public void AutoNamedClassInAffixInputAndMappingOfOneRule_IsNotUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			IMoAffixProcess rule = AddAffixProcessRule();
			AddInputNCContext(rule, natClass);
			AddModifyMapping(rule, natClass);

			Assert.That(IsUserDefined(natClass), Is.False);
		}

		/// <summary>
		/// The environment is attached to an allomorph so that a search past the environment
		/// would have further objects to reach.
		/// </summary>
		[Test]
		public void AutoNamedClassUsedByOneRuleAndAnEnvironment_IsNotUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			AddEnvironmentUsedByAnAllomorph(AddStandaloneNCContext(natClass));

			Assert.That(IsUserDefined(natClass), Is.False);
		}

		[Test]
		public void AutoNamedClassUsedByOneRuleAndALeftoverContext_IsNotUserDefined()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			AddStandaloneNCContext(natClass);

			Assert.That(IsUserDefined(natClass), Is.False);
		}

		[Test]
		public void SharedClassBecomesAutoGeneratedWhenOneRuleIsDeleted()
		{
			IPhNCFeatures natClass = AddGeneratedClass();
			AddStrucDescNCContext(AddRegularRule("rule A"), natClass);
			IPhSegRuleRHS rhsB = AddRegularRule("rule B");
			AddStrucDescNCContext(rhsB, natClass);
			Assert.That(IsUserDefined(natClass), Is.True, "two rules share the class");

			Cache.LanguageProject.PhonologicalDataOA.PhonRulesOS.Remove(rhsB.OwningRule);

			Assert.That(IsUserDefined(natClass), Is.False);
		}
	}
}
